using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void effect_automation_dialog(Control o,int index)
    {
        var stack=Get(effect_owner(o),"effects",new GArray()).AsGodotArray();if(index<0||index>=stack.Count)return;var effect=stack[index].AsGodotDictionary();using var effects=new AudioEffectsOperations();var supported=effects.automation_commands(effect["type"].AsString());var definitions=new Settings();var names=new GArray();foreach(var raw in effects.definition(effect["type"].AsString())["parameters"].AsGodotArray()){var field=raw.AsGodotDictionary();if(supported.ContainsKey(field["id"])){definitions[field["id"]]=field;names.Add(field["id"]);}}if(names.Count==0)return;var dialog=window(o,"Effect parameter automation",new Vector2I(720,430));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();var editor=NewCurveEditor(o,Session(o).Call("primary_clip").AsGodotObject());editor.Set("effect_id",effect["id"].AsString());editor.Set("parameter",names[0].AsString());editor.Set("minimum",definitions[names[0]].AsGodotDictionary()["min"].AsDouble());editor.Set("maximum",definitions[names[0]].AsGodotDictionary()["max"].AsDouble());label(host,"Drag curve points to automate this processor. Realtime uses the native approximation; offline commands update at up to 50 Hz (decoder frame boundaries). Long curves use an adaptive interval to bound render work.");var row=new HFlowContainer();host.AddChild(row);ChoiceAction(o,row,"Parameter",names,names[0].AsString(),value=>{editor.Set("parameter",value);editor.Set("minimum",definitions[value].AsGodotDictionary()["min"].AsDouble());editor.Set("maximum",definitions[value].AsGodotDictionary()["max"].AsDouble());editor.QueueRedraw();});ChoiceAction(o,row,"Interpolation",new GArray{"linear","smooth","hold"},"linear",value=>editor.Call("set_curve",value));NumberAction(o,row,"View seconds",editor.Get("duration").AsDouble(),.1,86400,.1,value=>{editor.Set("duration",value);editor.QueueRedraw();});editor.SizeFlagsVertical=Control.SizeFlags.ExpandFill;host.AddChild(editor);ActionButton(host,"Clear selected curve",()=>editor.Call("clear_points"));ActionButton(host,"Show in timeline lane",()=>{show_automation_editor_in_lane(o,editor);windowNode.QueueFree();});
    }
    public void arrangement_dialog(Control o)
    {
        var dialog=window(o,"Arrangement sections",new Vector2I(740,530));var dialogHost=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();label(dialogHost,"Move or resize a section to move/stretch its generated notes and chord events. Other sections stay put. Times are source-relative quarter-note beats at the generated arrangement tempo; they do not follow project conductor points.");var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};dialogHost.AddChild(scroll);var host=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(host);foreach(var raw in Items(Document(o),"sections")){var section=raw.AsGodotDictionary();var row=new HFlowContainer();host.AddChild(row);var input=new LineEdit{Text=section["name"].AsString(),CustomMinimumSize=new Vector2(120,0)};row.AddChild(input);input.TextSubmitted+=value=>SessionAction(o,"Rename section",()=>section["name"]=value);double start=section["start"].AsDouble(),duration=section["duration"].AsDouble();NumberAction(o,row,"Start",start,0,2048,.25,value=>start=value);NumberAction(o,row,"Length",duration,.25,1024,.25,value=>duration=value);ActionButton(row,"Apply",()=>transform_section(o,section["id"].AsString(),start,duration));ActionButton(row,"Regenerate",()=>{var settings=Dict(Document(o),"composer_settings").Duplicate(true);settings["seed"]=Get(settings,"seed",1).AsInt64()+1;compose(o,settings,"",section["id"].AsString());windowNode.QueueFree();});}ActionButton(dialogHost,"Add section marker",()=>{SessionAction(o,"Add arrangement section",()=>Items(Document(o),"sections").Add(new Settings{["id"]=NewAudioId(),["name"]="New section",["start"]=Position(o)*Document(o).Call("arrangement_tempo").AsDouble()/60,["duration"]=4.0}));windowNode.QueueFree();arrangement_dialog(o);});label(dialogHost,"Moving generated sections can create overlaps deliberately. Imported audio clips remain under direct timeline control.");
    }
    public void transform_section(Control o,string id,double start,double duration)
    {
        Settings? section=null;foreach(var raw in Items(Document(o),"sections")){var entry=raw.AsGodotDictionary();if(entry["id"].AsString()==id){section=entry;break;}}if(section==null)return;double previous=section["start"].AsDouble(),ratio=duration/Math.Max(.001,section["duration"].AsDouble());SessionAction(o,"Transform arrangement section",()=>{foreach(var raw in Items(Document(o),"actors")){var values=Dict(raw.AsGodotObject(),"values");foreach(var item in Get(values,"notes",new GArray()).AsGodotArray()){var note=item.AsGodotDictionary();if(Get(note,"section_id","").AsString()!=id)continue;note["start"]=start+(note["start"].AsDouble()-previous)*ratio;note["duration"]=note["duration"].AsDouble()*ratio;values[new StringName("notes_dirty")]=true;}}foreach(var raw in Items(Document(o),"chords")){var chord=raw.AsGodotDictionary();if(Get(chord,"section_id","").AsString()!=id)continue;chord["start"]=start+(chord["start"].AsDouble()-previous)*ratio;chord["duration"]=Get(chord,"duration",1).AsDouble()*ratio;}section["start"]=start;section["duration"]=duration;});render_dirty_notes(o);
    }
    public void sample_map_dialog(Control o)
    {
        var actor=Session(o).Call("primary_actor").AsGodotObject();if(actor==null)return;var values=Dict(actor,"values");var patch=Get(values,"instrument",new Settings()).AsGodotDictionary();var mappings=Get(patch,"multisamples",new GArray()).AsGodotArray();var dialog=window(o,"Multisample mapping",new Vector2I(750,520));var dialogHost=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};dialogHost.AddChild(scroll);var host=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(host);foreach(var raw in mappings){var mapping=raw.AsGodotDictionary();var row=new HFlowContainer();host.AddChild(row);label(row,Get(mapping,"sample","").AsString().GetFile());foreach(var info in new[]{("root_pitch",0.0,127.0,1.0),("low",0.0,127.0,1.0),("high",0.0,127.0,1.0),("velocity_low",0.0,1.0,.01),("velocity_high",0.0,1.0,.01)}){string key=info.Item1;double fallback=key=="root_pitch"?60:key=="high"?127:key=="velocity_high"?1:0;NumberAction(o,row,key,Get(mapping,key,fallback).AsDouble(),info.Item2,info.Item3,info.Item4,value=>EditAction(o,"Sample map",()=>{mapping[key]=value;values[new StringName("notes_dirty")]=true;}));}ActionButton(row,"Remove",()=>{SessionAction(o,"Remove sample mapping",()=>{mappings.Remove(mapping);patch["multisamples"]=mappings;values[new StringName("notes_dirty")]=true;});windowNode.QueueFree();sample_map_dialog(o);});}ActionButton(dialogHost,"Add sample",()=>{windowNode.QueueFree();o.Call("choose_instrument_sample");});ActionButton(dialogHost,"Render mapping",()=>{render_dirty_notes(o);windowNode.QueueFree();});
    }
}
